import path from "node:path";
import { fileURLToPath } from "node:url";
import { type CollectionConfig, ValidationError } from "payload";

import { expireCatalog } from "./shared";

const dirname = path.dirname(fileURLToPath(import.meta.url));

const webp = { format: "webp" as const, options: { quality: 80 } };

/** Responsive widths generated by Payload on upload (F-010 D-2: no Vercel image optimization). */
export const MEDIA_WIDTHS = [240, 480, 960, 1440] as const;

/** Largest photo accepted (F-011 CA-7). */
export const MAX_PHOTO_BYTES = 10 * 1024 * 1024;

/**
 * Product photos (F-010 D-1, minimal). Files go to Vercel Blob when a token is set, else to
 * `media/` on disk (local and CI). On Vercel the browser uploads straight to Blob (F-011 CA-7),
 * so a photo never goes through a function and its 4.5 MB body limit.
 */
export const Media: CollectionConfig = {
  slug: "media",
  labels: { singular: "Foto", plural: "Fotos" },
  // Product photos are public: the storefront serves them.
  access: { read: () => true },
  admin: { useAsTitle: "filename" },
  upload: {
    staticDir: path.resolve(dirname, "../../media"),
    mimeTypes: ["image/jpeg", "image/png", "image/webp"],
    formatOptions: webp,
    imageSizes: MEDIA_WIDTHS.map((width) => ({
      name: `w${width}`,
      width,
      withoutEnlargement: true,
      formatOptions: webp,
    })),
    adminThumbnail: "w480",
  },
  fields: [
    {
      name: "uploadProgress",
      type: "ui",
      admin: { components: { Field: "/components/admin/UploadProgress#UploadProgress" } },
    },
    {
      name: "alt",
      type: "text",
      label: "Texto alternativo",
      localized: true,
      admin: {
        description:
          "Describe la foto para quien no puede verla. Obligatorio en los 3 idiomas para publicar.",
      },
    },
  ],
  hooks: {
    // CA-7: the browser checks the size before uploading; this covers uploads through the server
    // (local, API), checked on the original file before it is converted to WebP.
    beforeOperation: [
      ({ args, operation, req }) => {
        if ((operation === "create" || operation === "update") && req.file) {
          if (req.file.size > MAX_PHOTO_BYTES) {
            throw new ValidationError({
              collection: "media",
              errors: [
                { path: "file", message: "La foto supera los 10 MB. Redúcela y vuelve a subirla." },
              ],
              req,
            });
          }
        }
        return args;
      },
    ],
    afterChange: [() => expireCatalog()],
    afterDelete: [() => expireCatalog()],
  },
};
